      hu: ["Kolumbusz előtti tárgyak.", "A gyarmati korszak vallási művészete.", "A városközpontban található.", "Coclé kulturális öröksége."],
      ro: ["Artefacte precolumbiene.", "Artă religioasă din epoca colonială.", "Situat în centrul orașului.", "Moștenirea culturală a Coclé."],
